function calculateScenario(id,values){
  id=normalizeId(id);const s=validateScenario(id,values);
  if(id==='concert-economics'){
    const potentialDemand=Math.floor(s.demand*Math.pow(s.ticketPrice/20,-s.elasticity));
    const attendance=Math.min(s.capacity,potentialDemand),venueCost=s.venueRate*s.capacity,variableCost=s.perGuest*attendance,totalCost=s.productionBudget+venueCost+variableCost,revenue=s.ticketPrice*attendance,profit=revenue-totalCost;
    return {ticketPrice:s.ticketPrice,capacity:s.capacity,potentialDemand,attendance,occupancy:100*attendance/s.capacity,unmetDemand:Math.max(0,potentialDemand-s.capacity),revenue,productionCost:s.productionBudget,venueCost,variableCost,totalCost,profit,returnOnCost:totalCost===0?null:100*profit/totalCost};
  }
  if(id==='conference-economics'){
    const attendance=Math.min(s.expectedAttendees,s.capacity),registrationRevenue=attendance*s.ticketPrice,workshopCost=s.workshopSeats*s.workshopRate,networkingCost=s.networkingSeats*s.networkingRate,cateringCost=attendance*s.catering,totalCost=s.venueCost+s.speakerBudget+workshopCost+networkingCost+cateringCost+s.otherFixed,revenue=registrationRevenue+s.sponsor;
    return {attendance,capacity:s.capacity,registrationRevenue,sponsorRevenue:s.sponsor,revenue,workshopCost,networkingCost,cateringCost,totalCost,profit:revenue-totalCost,workshopAccess:attendance?100*Math.min(attendance,s.workshopSeats)/attendance:null,networkingAccess:attendance?100*Math.min(attendance,s.networkingSeats)/attendance:null,cateringProvision:s.catering,budgetGap:Math.max(0,totalCost-s.availableBudget)};
  }
  let inventory=s.openingInventory,cumulativeOutput=0,delayedUnits=0,sales=0,revenue=0,componentConsumedCost=0,supplierPremiums=0,purchaseCash=0,carryingCosts=0,costOfGoodsSold=0,operatingCosts=0,produced=0,received=0;
  const stock=[{qty:s.openingInventory,premium:0}],finished=[],history=[];
  for(let day=1;day<=s.elapsedDays;day++){
    received=0;
    for(const order of [{day:1+s.supplierDelay,qty:s.deliveryQuantity,premium:0},{day:s.alternativeDay,qty:s.alternativeQuantity,premium:s.alternativePremium}])if(order.day===day&&order.qty){stock.push({qty:order.qty,premium:order.premium});inventory+=order.qty;received+=order.qty;purchaseCash+=order.qty*(s.componentCost+order.premium);}
    produced=Math.min(s.target,inventory);let need=produced,dayPremium=0;
    for(const batch of stock){const take=Math.min(need,batch.qty);batch.qty-=take;need-=take;dayPremium+=take*batch.premium;}
    inventory-=produced;cumulativeOutput+=produced;delayedUnits+=s.target-produced;componentConsumedCost+=produced*s.componentCost;supplierPremiums+=dayPremium;
    if(produced)finished.push({qty:produced,cost:s.nonComponentCost+s.componentCost+dayPremium/produced});
    let sell=s.sellImmediately?finished.reduce((n,b)=>n+b.qty,0):s.dailySales;
    for(const batch of finished){const sold=Math.min(sell,batch.qty);batch.qty-=sold;sell-=sold;sales+=sold;revenue+=sold*s.sellingPrice;costOfGoodsSold+=sold*batch.cost;}
    carryingCosts+=inventory*s.carryingCost;operatingCosts+=s.operatingCost;
    history.push({day,received,produced,closingInventory:inventory});
  }
  return {day:s.elapsedDays,produced,received,inventory,cumulativeOutput,delayedUnits,sales,finishedInventory:finished.reduce((n,b)=>n+b.qty,0),revenue,componentConsumedCost,supplierPremiums,purchaseCash,openingInventoryValue:s.openingInventory*s.componentCost,carryingCosts,operatingCosts,costOfGoodsSold,profit:revenue-costOfGoodsSold-carryingCosts-operatingCosts,history};
}

function defaults(id){const l=LESSONS[normalizeId(id)];if(!l)throw new Error('Choose a supported lesson.');return {...Object.fromEntries(l.fields.map(f=>[f[0],f[6]])),...(l.scene==='factory'?{elapsedDays:0,sellImmediately:true}:{})};}

function normalizeId(id){return {concert:'concert-economics',conference:'conference-economics',factory:'factory-supply-chain'}[id]||id;}

function validateScenario(id,values={}){
  id=normalizeId(id);const l=LESSONS[id];if(!l)throw new Error('Choose a supported lesson.');
  if(!values||typeof values!=='object'||Array.isArray(values))throw new Error('Scenario must be an object.');
  const s={...defaults(id),...values};
  const integerKeys=new Set(['capacity','demand','expectedAttendees','workshopSeats','networkingSeats','target','openingInventory','supplierDelay','deliveryQuantity','alternativeQuantity','alternativeDay','dailySales']);
  for(const [key,en,,min,max] of l.fields){const integer=integerKeys.has(key);if(typeof s[key]!=='number'||!Number.isFinite(s[key])||s[key]<min||s[key]>max||(integer&&!Number.isInteger(s[key])))throw new Error(`${en}: enter ${integer?'an integer':'a number'} between ${min} and ${max}.`);}
  if(l.scene==='factory'&&(!Number.isInteger(s.elapsedDays)||s.elapsedDays<0||s.elapsedDays>30||typeof s.sellImmediately!=='boolean'))throw new Error('Choose a day from 0–30 and a sales assumption.');
  const allowed=new Set([...l.fields.map(f=>f[0]),...(l.scene==='factory'?['elapsedDays','sellImmediately']:[])]);
  for(const key of Object.keys(values))if(!allowed.has(key))throw new Error(`Unknown scenario input: ${key}`);
  return s;
}

function changeExplanation(id,s,previous,language='en'){
 const de=language==='de',c=calculateScenario(id,s),f=n=>n===null?'—':new Intl.NumberFormat(de?'de-DE':'en-US',{maximumFractionDigits:2}).format(n),cu=de?'GE':'CU';
 if(!previous)return de?'Noch keine frühere Einstellung zum Vergleich. Ändere eine Entscheidung: Hier siehst du danach Ursache und Wirkung.':'There is no earlier setting to compare yet. Try a decision: its cause and effect will appear here.';
 const a=calculateScenario(id,previous),keys=Object.keys(s).filter(k=>s[k]!==previous[k]);
 if(!keys.length)return de?'Die Einstellungen sind unverändert.':'The settings are unchanged.';
 if(id==='concert-economics'){
  const price=keys.includes('ticketPrice')?(de?`Ticketpreis: ${f(previous.ticketPrice)} → ${f(s.ticketPrice)} GE. `:`Ticket price: ${f(previous.ticketPrice)} → ${f(s.ticketPrice)} CU. `):'';
  const capacity=keys.includes('capacity')?(de?`Saalgröße: ${f(previous.capacity)} → ${f(s.capacity)} Plätze. `:`Venue size: ${f(previous.capacity)} → ${f(s.capacity)} places. `):'';
  const demand=keys.includes('demand')?(de?`Auch die Nachfrageannahme wurde von ${f(previous.demand)} auf ${f(s.demand)} geändert. `:`The demand assumption also changed from ${f(previous.demand)} to ${f(s.demand)}. `):'';
  const cause=keys.length===1&&keys[0]==='capacity'?(de?`Mehr Platz erzeugt keine Käufer. Die Saalmiete ändert sich von ${f(a.venueCost)} auf ${f(c.venueCost)} GE. `:`Extra space does not create buyers. Venue hire changes from ${f(a.venueCost)} to ${f(c.venueCost)} CU. `):keys.length===1&&keys[0]==='ticketPrice'?(de?`Die Preisannahme verändert die Nachfrage; Kosten pro anwesendem Gast ändern sich von ${f(a.variableCost)} auf ${f(c.variableCost)} GE. `:`The price assumption changes demand; costs for attending guests change from ${f(a.variableCost)} to ${f(c.variableCost)} CU. `):'';
  return price+capacity+demand+(de?`Erwartete Gäste: ${f(a.attendance)} → ${f(c.attendance)}. Ticketumsatz: ${f(a.revenue)} → ${f(c.revenue)} GE${a.revenue===c.revenue?' (unverändert)':''}. `:`Expected guests: ${f(a.attendance)} → ${f(c.attendance)}. Ticket revenue: ${f(a.revenue)} → ${f(c.revenue)} CU${a.revenue===c.revenue?' (unchanged)':''}. `)+cause+(de?`Gesamtkosten: ${f(a.totalCost)} → ${f(c.totalCost)} GE. Ergebnis: ${f(a.profit)} → ${f(c.profit)} GE${c.profit<0?' (Verlust)':''}.`:`Total costs: ${f(a.totalCost)} → ${f(c.totalCost)} CU. Profit: ${f(a.profit)} → ${f(c.profit)} CU${c.profit<0?' (loss)':''}.`);
 }
 if(id==='conference-economics'){
  const workshop=keys.includes('workshopSeats')?(de?`Workshopplätze: ${f(previous.workshopSeats)} → ${f(s.workshopSeats)}. ${f(Math.min(c.attendance,s.workshopSeats)-Math.min(a.attendance,previous.workshopSeats))} zusätzliche Personen können gleichzeitig teilnehmen. Zugang: ${f(a.workshopAccess)}% → ${f(c.workshopAccess)}%. Einrichtungskosten: ${f(a.workshopCost)} → ${f(c.workshopCost)} GE. `:`Workshop places: ${f(previous.workshopSeats)} → ${f(s.workshopSeats)}. ${f(Math.min(c.attendance,s.workshopSeats)-Math.min(a.attendance,previous.workshopSeats))} more people can join at once. Access: ${f(a.workshopAccess)}% → ${f(c.workshopAccess)}%. Setup costs: ${f(a.workshopCost)} → ${f(c.workshopCost)} CU. `):'';
  return workshop+(de?`Einnahmen: ${f(a.revenue)} → ${f(c.revenue)} GE. Kosten: ${f(a.totalCost)} → ${f(c.totalCost)} GE. Verbleibendes Geld: ${f(a.profit)} → ${f(c.profit)} GE. Die Ausgabengrenze von ${f(s.availableBudget)} GE ist separat; Kosten liegen ${f(c.budgetGap)} GE darüber.`:`Income: ${f(a.revenue)} → ${f(c.revenue)} CU. Costs: ${f(a.totalCost)} → ${f(c.totalCost)} CU. Money left: ${f(a.profit)} → ${f(c.profit)} CU. Your ${f(s.availableBudget)} CU spending limit is separate; costs are ${f(c.budgetGap)} CU above it.`);
 }
 const row=c.history.at(-1),opening=row?c.inventory+c.produced-c.received:s.openingInventory;
 if(keys.length===1&&keys[0]==='elapsedDays')return de?`Tag ${c.day}: ${f(opening)} Teile zu Beginn + ${f(c.received)} gelieferte Teile, dann ${f(c.produced)} verbaute Teile = ${f(c.inventory)} Teile am Ende. Heute ${f(c.produced)} Autos gebaut; bisher ${f(c.cumulativeOutput)} von ${f(s.target*c.day)} geplanten Autos. ${c.produced<s.target?'Fehlende Teile begrenzen die Produktion.':'Genug Teile für das Tagesziel.'}`:`Day ${c.day}: ${f(opening)} starting parts + ${f(c.received)} delivered, then ${f(c.produced)} used = ${f(c.inventory)} parts left. Built ${f(c.produced)} cars today; ${f(c.cumulativeOutput)} so far against a ${f(s.target*c.day)}-car plan. ${c.produced<s.target?'Missing parts limit production.':'Enough parts to reach today’s target.'}`;
 return de?`Mit den neuen Einstellungen neu gestartet (Tag ${c.day}). Anfangsbestand: ${f(s.openingInventory)} Teile. Hauptlieferung: ${f(s.deliveryQuantity)} Teile an Tag ${s.supplierDelay+1}. ${s.alternativeQuantity?`Ersatzlieferung: ${f(s.alternativeQuantity)} Teile an Tag ${s.alternativeDay}, je ${f(s.componentCost+s.alternativePremium)} GE.`:'Keine Ersatzlieferung geplant.'}`:`Restarted with the new settings (day ${c.day}). Starting stock: ${f(s.openingInventory)} parts. Main delivery: ${f(s.deliveryQuantity)} parts on day ${s.supplierDelay+1}. ${s.alternativeQuantity?`Backup delivery: ${f(s.alternativeQuantity)} parts on day ${s.alternativeDay}, at ${f(s.componentCost+s.alternativePremium)} CU each.`:'No backup delivery is scheduled.'}`;
}

function validateRequest(input){
  if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Send a lesson request object.');
  const topicId=normalizeId(input.topicId||input.lessonId);
  if(!LESSONS[topicId])throw new Error('Choose one of the three lessons.');
  if(!['en','de'].includes(input.language))throw new Error('Choose English or German.');
  if(typeof input.question!=='string'||!input.question.trim()||input.question.length>600)throw new Error('Ask a question using 1–600 characters.');
  for(const key of ['requestId','sessionId'])if(typeof input[key]!=='string'||!/^[a-zA-Z0-9_-]{8,80}$/.test(input[key]))throw new Error('Refresh your session and try again.');
  const revision=input.scenarioRevision??0;if(!Number.isInteger(revision)||revision<0||revision>10000000)throw new Error('Invalid scenario revision.');
  return {requestId:input.requestId,sessionId:input.sessionId,topicId,language:input.language,question:input.question.trim(),scenario:validateScenario(topicId,input.scenario),scenarioRevision:revision,inputMode:input.inputMode==='voice'?'voice':'text',previousScenario:input.previousScenario?validateScenario(topicId,input.previousScenario):null};
}

function preparedLesson(request,reason='prepared'){
  const id=normalizeId(request.topicId),l=LESSONS[id],p=approvedParagraphs(request),q=request.question.toLowerCase();
  const key=/chang|änd|fall|rise|sink|stieg/.test(q)?'change':/cost|kosten|budget|preis/.test(q)?'costs':/demand|nachfrage|guest|publikum|workshop|part|teil|bottleneck/.test(q)?'demand':/sponsor|revenue|umsatz|sales/.test(q)?'revenue':'overview';
  return {contractVersion:2,lessonId:id,lessonVersion:l.version,simulationVersion:l.version,scenarioRevision:request.scenarioRevision??0,requestId:request.requestId,language:request.language,explanation:p[key]+' '+(key==='overview'?p.limits:p.overview),paragraphIds:[key,key==='overview'?'limits':'overview'],calculationResults:calculateScenario(id,request.scenario),assumptions:[p.limits,p.demand],sceneActions:[{type:'highlight',target:l.zones[key==='costs'?1:0]}],suggestedFollowup:l.questions[request.language][0],sourceReferences:[{title:request.language==='de'?'Modellannahmen':'Model assumptions',url:'/methodology?lesson='+id}],fallbackUsed:true,delivery:reason};
}

