 if(id==='concert-economics'){
  const price=keys.includes('ticketPrice')?(de?`Ticketpreis: ${f(previous.ticketPrice)} → ${f(s.ticketPrice)} GE. `:`Ticket price: ${f(previous.ticketPrice)} → ${f(s.ticketPrice)} CU. `):'';
